<template><section><header class="d-flex justify-content-between align-items-end mb-4"><div><RouterLink to="/cms/courses" class="small text-secondary"><i class="bi bi-arrow-left"></i> Danh sách khóa học</RouterLink><h1 class="page-title mt-2">Nội dung: Vue.js 3</h1><p class="page-subtitle mb-0">Sắp xếp chương và bài học theo lộ trình đào tạo.</p></div><button class="btn btn-brand" @click="addChapter"><i class="bi bi-plus-lg"></i> Thêm chương</button></header><div class="builder"><article v-for="(chapter,index) in localChapters" :key="chapter.id" class="app-card chapter-card"><header><span class="drag"><i class="bi bi-grip-vertical"></i></span><span class="number">{{ index+1 }}</span><div><strong>{{ chapter.title }}</strong><small>{{ chapter.lessons.length }} bài học</small></div><div class="ms-auto"><button class="btn btn-light btn-sm"><i class="bi bi-pencil"></i></button></div></header><div class="lesson" v-for="(lesson,lIndex) in chapter.lessons" :key="lesson.id"><i class="bi bi-grip-vertical text-secondary"></i><span class="type"><i class="bi bi-play-btn"></i></span><div><strong>{{ lesson.title }}</strong><small>Video tương tác • {{ lesson.duration }}</small></div><span v-if="lesson.completed" class="badge badge-soft-success">Hoàn thiện</span><button class="btn btn-light btn-sm"><i class="bi bi-three-dots"></i></button></div><button class="add-lesson" @click="addLesson(index)"><i class="bi bi-plus-circle"></i> Thêm bài học</button></article></div></section></template>
<script setup>import { ref } from 'vue';import { chapters } from '../../data/demo';const localChapters=ref(structuredClone(chapters));function addChapter(){localChapters.value.push({id:Date.now(),title:`Chương ${localChapters.value.length+1}`,lessons:[]})}function addLesson(index){localChapters.value[index].lessons.push({id:Date.now(),title:'Bài học mới',duration:'00:00'})}</script>
<style scoped>.builder{display:grid;gap:1rem}.chapter-card{overflow:hidden}.chapter-card>header{display:flex;align-items:center;gap:.8rem;padding:1rem 1.2rem;background:#f8faf9}.chapter-card header>div:not(.ms-auto){display:grid}.chapter-card small{color:#7a8a84;display:block}.drag{color:#a2afa9}.number{width:32px;height:32px;border-radius:8px;background:#07875a;color:white;display:grid;place-items:center;font-weight:800}.lesson{display:grid;grid-template-columns:20px 40px 1fr auto auto;align-items:center;gap:.75rem;padding:.8rem 1.2rem;border-top:1px solid #e8eeeb}.type{width:36px;height:36px;border-radius:9px;background:#eaf2fa;color:#005099;display:grid;place-items:center}.lesson strong{font-size:.88rem}.add-lesson{border:0;background:white;color:#07875a;font-weight:700;padding:1rem 1.2rem;text-align:left}@media(max-width:600px){.lesson{grid-template-columns:20px 36px 1fr auto}.lesson>.badge{display:none}}</style>
